use verus::prelude::*;

verus! {

    // Given:
    // n = number of items, 1 <= n <= 20
    // d = coverage radius, 1 <= d <= 20
    //
    // Each inspector covers a contiguous block of length 2*d + 1 items.
    // Goal: minimum number of inspectors to cover all n items.
    // Output: ceil(n / (2*d + 1))
    //
    // The result must be between 1 and n inclusive.

    #[spec]
    fn coverage_length(d: i8) -> i8 {
        2 * d + 1
    }

    #[verifier(external_body)]
    #[ensures(result >= 1 && result <= n)]
    #[ensures(result * coverage_length(d) >= n)]
    #[ensures((result - 1) * coverage_length(d) < n || result == 1)]
    fn min_inspectors(n: i8, d: i8) -> i8 {
        // Implementation: integer division ceiling
        // ceil(n / (2*d + 1)) = (n + (2*d)) / (2*d + 1)

        let coverage = 2 * d + 1;
        let numerator = n + (coverage - 1);
        numerator / coverage
    }

}